$('saveRegion').onclick=()=>action(async()=>{const row=images[index],view_id=$('imageView').value;if(!row||!view_id||row.view_id!==view_id)throw new Error(tr('regionNeedView'));const operator=$('operator').value.trim();if(!operator)throw new Error(tr('operator')+' required');const name=$('regionName').value.trim();if(!name)throw new Error(tr('regionName')+' required');const data={mission,view_id,kind:$('drawMode').value,name,polygon:regionDraft,role:$('regionRole').value,operator};if(editingRegion){data.action='update';data.region_id=editingRegion;}else data.action='create';await api('/api/view-regions',data);regionDraft=[];editingRegion='';$('regionName').value='';updateRegionControls();await refreshRegions();});
