async function refreshPlateCrops(imageId=null){
 if(!mission)return;
 if(plateCropMission!==mission){plateCropMission=mission;plateCropOffset=0;}
 const current=mission,selected=missions.find(item=>item.id===mission);
 $('plateFolderInfo').textContent=selected?.output_root?tr('plateSavedFolder')+': '+selected.output_root+'/plate-crops/'+mission:'';
 const url='/api/plates/page?mission='+encodeURIComponent(mission)+'&limit='+plateCropLimit+'&offset='+plateCropOffset+(imageId?'&image='+encodeURIComponent(imageId):'');
 const page=await api(url);if(current!==mission)return;
 if(!page.items.length&&plateCropOffset>0&&plateCropOffset>=page.total){plateCropOffset=Math.max(0,Math.floor((page.total-1)/plateCropLimit)*plateCropLimit);return refreshPlateCrops(imageId);}
 plateCropTotal=page.total;const items=page.items;
 const start=items.length?plateCropOffset+1:0,end=plateCropOffset+items.length;
 $('platePageStatus').textContent=tr('platePageRange')+' '+start+'–'+end+' '+tr('of')+' '+plateCropTotal;
 $('platePreviousPage').disabled=plateCropOffset<=0;$('plateNextPage').disabled=plateCropOffset+plateCropLimit>=plateCropTotal;
 const list=$('plateCrops');list.replaceChildren();
 if(!items.length){const empty=document.createElement('p');empty.className='muted';empty.textContent=tr('plateEmpty');list.append(empty);return;}
 for(const item of items){const card=document.createElement('article');card.className='plate-card';
  const image=document.createElement('img');image.src='/api/plate-crop?mission='+encodeURIComponent(mission)+'&crop='+encodeURIComponent(item.id);image.alt=tr('plateReviewHeading');
  const context=document.createElement('img');context.className='plate-context';context.src=item.source_kind==='video'?'/api/plate-context?mission='+encodeURIComponent(mission)+'&crop='+encodeURIComponent(item.id):'/api/image?mission='+encodeURIComponent(mission)+'&image='+encodeURIComponent(item.image_id);context.alt=item.source_name;
  const meta=document.createElement('div');meta.className='plate-meta';
  const source=document.createElement('strong');source.textContent=tr('plateSource')+': '+item.source_name;
  const country=document.createElement('span');country.className='muted';country.textContent=item.mission_country_context?tr('plateMissionCountry')+': '+item.mission_country_context+' ('+tr('missionCountryContextBasis')+')':'';
  const score=document.createElement('span');score.textContent=tr('plateConfidence')+': '+Number(item.confidence).toFixed(3);
  const focus=document.createElement('span');focus.textContent=item.blur_laplacian_variance!=null&&Number.isFinite(Number(item.blur_laplacian_variance))?tr('plateFocusReference')+': '+Number(item.blur_laplacian_variance).toFixed(1):'';
  const frameTime=document.createElement('span');if(item.source_kind==='video'){const seconds=item.time_base_den?item.pts*item.time_base_num/item.time_base_den:null;frameTime.textContent=tr('plateFrameTime')+': '+item.frame_index+' · '+(seconds===null?'?':seconds.toFixed(3)+'s')+(item.capture_utc?' · '+item.capture_utc:'');}
  const state=document.createElement('span');state.className='plate-state';state.textContent=tr(item.decision==='approved'?'plateApproved':item.decision==='rejected'?'plateRejected':'platePending');
  const controls=document.createElement('div');controls.className='plate-review-buttons';
  for(const [decision,key] of [['approved','plateApprove'],['rejected','plateReject']]){const button=document.createElement('button');button.type='button';button.textContent=tr(key);button.onclick=()=>action(async()=>{const operator=$('plateOperator').value.trim();if(!operator)throw new Error(tr('plateNeedOperator'));await api('/api/plates/review',{mission,crop_id:item.id,expected_revision:item.revision||0,decision,operator});await refreshPlateCrops();});controls.append(button);}
  const contextLabel=document.createElement('span');contextLabel.className='muted';contextLabel.textContent=item.source_name;
  meta.append(source);if(country.textContent)meta.append(country);meta.append(score);if(focus.textContent)meta.append(focus);if(item.source_kind==='video')meta.append(frameTime);meta.append(state,controls);
  card.append(image,contextLabel,context,meta);list.append(card);
 }
}

